package fixture

import "testing"

func TestGCD(t *testing.T) {
	cases := [][3]int{{12, 18, 6}, {17, 5, 1}, {0, 5, 5}}
	for _, c := range cases {
		if got := GCD(c[0], c[1]); got != c[2] {
			t.Fatalf("GCD(%d,%d) = %d, want %d", c[0], c[1], got, c[2])
		}
	}
}
